def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    value = 0.0
    total = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        shell = (props.get(element) or {}).get('pymatgen_valence_subshell')
        if fraction is not None and fraction > 0 and shell is not None and len(shell) == 2:
            l = shell[0]
            count = shell[1]
            if l is not None and count is not None:
                total += fraction
                if l == 3:
                    value += fraction * max(0.0, count)
    return value / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    occupied = 0.0
    spheres = 0.0
    for site in s.get('sites') or []:
        o = site.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        occupied += o
        r = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        if r is not None and r > 0:
            spheres += o * r ** 3
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        v = s.get('volume_per_atom_A3')
        volume = v * occupied if v is not None and v > 0 else 0.0
    return 4.0 * pi * spheres / (3.0 * volume) if volume > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    nearest = [inf] * n
    edges = s.get('neighbors') or []
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[j] > 0 and d is not None and d > 0:
            nearest[i] = min(nearest[i], d)
    coordination = [0.0] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and d <= 1.25 * nearest[i]:
            coordination[i] += occ[j]
    total = sum(occ)
    if total <= 0:
        return 0.0
    mean = sum(occ[i] * coordination[i] for i in range(n)) / total
    return sqrt(max(0.0, sum(occ[i] * (coordination[i] - mean) ** 2 for i in range(n)) / total))

