                closest[i] = min(closest[i], d / (a + b))
    total = sum(occ[i] for i in range(n) if isfinite(closest[i]))
    return sum(occ[i] * closest[i] for i in range(n) if isfinite(closest[i])) / total if total > 0 else 0.0

