def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    groups = [(props.get(x.get('element')) or {}).get('group') for x in sites]
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    bonds = [0.0] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            a = radii[i]
            b = radii[j]
            g = groups[i]
            if g is not None and 14 <= g <= 17 and a is not None and b is not None and a > 0 and b > 0:
                if d <= 1.35 * (a + b):
                    bonds[i] += occ[j] * exp(max(-8.0, min(2.0, (a + b - d) / 0.3)))
    value = 0.0
    total = 0.0
    for i in range(n):
        g = groups[i]
        if g is not None and 14 <= g <= 17 and radii[i] is not None and radii[i] > 0:
            target = 18.0 - g
            value += occ[i] * max(0.0, target - bonds[i]) / target
            total += occ[i]
    return value / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    if n == 0:
        return 0.0
    props = s.get('element_properties') or {}
    radii = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    adjacency = [[] for i in range(n)]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        image = edge.get('image')
        if 0 <= i < n and 0 <= j < n and occ[i] > 0 and occ[j] > 0 and d is not None and d > 0 and image is not None and len(image) == 3:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0 and d <= 1.2 * (a + b):
                adjacency[i] += [(j, tuple(image))]
    shifts = [None] * n
    best = 0
    for root in range(n):
        if shifts[root] is not None or occ[root] <= 0:
            continue
        shifts[root] = (0, 0, 0)
        queue = [root]
        cycles = []
        for q in range(n):
            if q >= len(queue):
                break
            i = queue[q]
            for j, image in adjacency[i]:
                candidate = tuple(shifts[i][k] + image[k] for k in range(3))
                if shifts[j] is None:
                    shifts[j] = candidate
                    queue += [j]
                else:
                    residual = tuple(candidate[k] - shifts[j][k] for k in range(3))
                    if any(x != 0 for x in residual):
                        cycles += [residual]
        if len(cycles) > 0:
            rank = int(np.linalg.matrix_rank(np.asarray(cycles, dtype=float), tol=1e-7))
            best = max(best, rank)
            if best == 3:
                return 3.0
    return float(best)
